draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // symbolic object: a circle with a line through it
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 - 20 * Math.sin(t), H/2);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2);
  ctx.stroke();
  // add text to represent the number 1037
  ctx.font = '40px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('1037', W/2, H/2 + 70 + 20 * Math.cos(t));
  ctx.restore();
}
